Habacuque 3 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"O que o profeta pede ao Senhor no meio da ira?","o":["Que se lembre da misericórdia","Que destrua os inimigos","Que mande chuva sobre a terra","Que deixe de falar com ele"],"c":0,"v":2,"e":"No versículo 2, Habacuque pede: \"Na tua ira, lembra-te da misericórdia.\""},
 {"t":"multipla","p":"De onde o profeta diz que Deus vem?","o":["Do Egito","De Temã","De Sião","Do Líbano"],"c":1,"v":3,"e":"O versículo 3 diz que \"Deus vem de Temã, e do monte de Parã vem o Santo\"."},
 {"t":"multipla","p":"O que ia diante de Deus?","o":["Um exército de anjos","Uma nuvem de fumaça","A peste","Um vento forte"],"c":2,"v":5,"e":"O versículo 5 diz que \"diante dele ia a peste\"."},
 {"t":"multipla","p":"De quem eram as tendas que o profeta viu em aflição?","o":["De Edom","De Moabe","Da Assíria","De Cuch"],"c":3,"v":7,"e":"No versículo 7, o profeta diz: \"Vi as tendas de Cuch em aflição\"."},
 {"t":"multipla","p":"Para que o Senhor saiu, segundo o profeta?","o":["Para julgar os sacerdotes","Para a salvação do seu povo","Para destruir o templo","Para chamar outro profeta"],"c":1,"v":13,"e":"O versículo 13 diz: \"Saíste para a salvação do teu povo, para salvar o teu ungido\"."},
 {"t":"cv","p":"Depois de ouvir, o profeta diz que deve esperar em silêncio o dia da angústia.","c":true,"v":16,"e":"No versículo 16, ele diz: \"em silêncio, devo esperar o dia da angústia\"."},
 {"t":"cv","p":"O profeta diz que só vai se alegrar no Senhor se a figueira florescer e houver fruto na videira.","c":false,"v":18,"e":"Os versículos 17 e 18 dizem o contrário: mesmo que a figueira não floresça e falte fruto, \"contudo, eu me alegro no Senhor\"."},
 {"t":"cv","p":"O profeta diz que o Senhor fará os pés dele como os das corças.","c":true,"v":19,"e":"O versículo 19 diz que o Senhor \"fará com que meus pés sejam como os das corças\"."}
]}

Habacuque 1 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"O que Habacuque diz que grita ao Senhor sem ser salvo?","o":["\"Violência!\"","\"Socorro!\"","\"Misericórdia!\"","\"Justiça!\""],"c":0,"v":2,"e":"No versículo 2, o profeta pergunta até quando gritará \"Violência!\" sem que o Senhor o salve."},
 {"t":"multipla","p":"Segundo Habacuque, o que acontece com a lei?","o":["É esquecida","Se afrouxa","É reescrita","É abolida"],"c":1,"v":4,"e":"No versículo 4, Habacuque diz que a lei se afrouxa e a justiça nunca se manifesta."},
 {"t":"multipla","p":"Que nação o Senhor diz que está suscitando?","o":["Os assírios","Os egípcios","Os caldeus","Os filisteus"],"c":2,"v":6,"e":"No versículo 6, o Senhor diz que suscita os caldeus, nação amarga e impetuosa."},
 {"t":"multipla","p":"Os cavalos dos caldeus são mais ágeis do que quais animais?","o":["Gazelas","Leopardos","Leões","Cervos"],"c":1,"v":8,"e":"No versículo 8, os cavalos são descritos como mais ágeis do que leopardos e mais ferozes do que lobos."},
 {"t":"multipla","p":"Como os caldeus tomam as fortalezas?","o":["Com aríetes","Pela fome","Por traição","Amontoando terra"],"c":3,"v":10,"e":"No versículo 10, os caldeus riem das fortalezas e as tomam amontoando terra."},
 {"t":"cv","p":"Habacuque reconhece que o Senhor estabeleceu os caldeus para executar juízo.","c":true,"v":12,"e":"No versículo 12, o profeta diz que o Senhor os estabeleceu para executar juízo e os fundou para servir de disciplina."},
 {"t":"cv","p":"Habacuque pergunta por que os homens seriam tratados como ovelhas sem pastor.","c":false,"v":14,"e":"No versículo 14, a comparação é com peixes do mar e répteis que não têm quem os governe."},
 {"t":"cv","p":"O inimigo oferece sacrifícios e queima incenso à sua rede.","c":true,"v":16,"e":"No versículo 16, ele oferece sacrifícios à sua rede e queima incenso à sua varredoura, porque por elas enriqueceu."}
]}

Habacuque 2 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Onde o profeta diz que ficaria esperando a resposta de Deus à sua queixa?","o":["No templo de Jerusalém","À porta da cidade","Na sua torre de vigia","No alto de um monte"],"c":2,"v":1,"e":"No versículo 1, o profeta diz que estará na sua torre de vigia para ver o que Deus lhe dirá."},
 {"t":"multipla","p":"O que o Senhor mandou o profeta fazer com a visão?","o":["Escrevê-la e torná-la clara em tábuas","Guardá-la em segredo até o tempo certo","Contá-la somente aos sacerdotes","Anunciá-la nas portas do rei"],"c":0,"v":2,"e":"No versículo 2, o Senhor manda escrever a visão e torná-la clara em tábuas, para que até quem passa correndo possa lê-la."},
 {"t":"multipla","p":"Em contraste com o soberbo, pelo que o justo viverá?","o":["Pela sua força","Pela sua fé","Pelas suas riquezas","Pela sua sabedoria"],"c":1,"v":4,"e":"No versículo 4, depois de falar do soberbo, o texto diz que o justo viverá pela sua fé."},
 {"t":"multipla","p":"Segundo um dos \"ai\" do capítulo, com que se edifica a cidade condenada?","o":["Com ouro e prata","Com pedras do Líbano","Com tributos dos povos","Com sangue"],"c":3,"v":12,"e":"No versículo 12, o texto diz: Ai daquele que edifica a cidade com sangue e que a funda com iniquidade."},
 {"t":"multipla","p":"A que é comparada a terra cheia do conhecimento da glória do Senhor?","o":["À luz que enche o dia","À chuva que rega o campo","Às águas que cobrem o mar","Às estrelas que enchem o céu"],"c":2,"v":14,"e":"No versículo 14, a terra se encherá do conhecimento da glória do Senhor como as águas cobrem o mar."},
 {"t":"cv","p":"A quem embriaga o companheiro para ver sua nudez, o cálice da mão direita do Senhor também retornará.","c":true,"v":16,"e":"No versículo 16, depois do ai contra quem embriaga o companheiro, o texto diz que o cálice da mão direita do Senhor retornará a ele."},
 {"t":"cv","p":"O capítulo diz que os ídolos de madeira e pedra cobertos de ouro e prata têm fôlego dentro deles.","c":false,"v":19,"e":"No versículo 19, o texto diz que o ídolo está coberto de ouro e prata, mas em seu interior não há fôlego algum."},
 {"t":"cv","p":"O capítulo termina dizendo que o Senhor está em seu santo templo e que toda a terra deve ficar em silêncio diante dele.","c":true,"v":20,"e":"O versículo 20 diz que o Senhor está em seu santo templo e que toda a terra permaneça em silêncio diante dele."}
]}
